SecureAccelerator::CalculateMeasurement(RSA* r) {
 unsigned char *hash = (unsigned 
char*)malloc(SHA256_DIGEST_LENGTH);
 SHA256_CTX sha256;
 SHA256_Init(&sha256);
 SHA256_Update(&sha256, LOADED_KERNEL, KERNEL_SIZE);
 SHA256_Final(hash, &sha256);
 std::string hash_str = (char*)hash;
 std::string signedHash = signMessage(hash_str, r);
 return hash_str + std::string("\x00") + signedHash;
}
